cr_business_template.create_user_id,cr_business_template.operation_auth_type,cr_business_template.operation_auth_ids, cr_business_template.read_auth_type, cr_business_template.read_auth_ids,
cr_business_template.create_time,b.scene_type
from cr_business_template

    inner JOIN cr_team_template b
    on cr_business_template.resource_id= b.business_template_id


    cr_business_template.resource_id in


